#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 11174 - Homer Simpson
 * 
 * 解題思路：
 * 1. 這是一個完全背包問題的變體。
 * 2. 令 dp[i] 為在時間 i 內能吃掉的最大漢堡數量。
 * 3. 初始化 dp 陣列為 -1，dp[0] = 0。
 * 4. 轉移方程：dp[i] = max(dp[i-m], dp[i-n]) + 1 (若 i-m 或 i-n 合法)。
 * 5. 先檢查 dp[t] 是否有解。
 * 6. 若無解，從 t-1 開始往下找第一個有解的 dp[i]，輸出 dp[i] 和 (t-i)。
 */

int main() {
    int m, n, t;
    while (cin >> m >> n >> t) {
        vector<int> dp(t + 1, -1);
        dp[0] = 0;
        for (int i = 1; i <= t; ++i) {
            int takeM = (i >= m && dp[i - m] != -1) ? dp[i - m] + 1 : -1;
            int takeN = (i >= n && dp[i - n] != -1) ? dp[i - n] + 1 : -1;
            dp[i] = max(takeM, takeN);
        }

        if (dp[t] != -1) {
            cout << dp[t] << endl;
        } else {
            for (int i = t - 1; i >= 0; --i) {
                if (dp[i] != -1) {
                    cout << dp[i] << " " << t - i << endl;
                    break;
                }
            }
        }
    }
    return 0;
}
